'use strict';
/* A buildable copy of this checkout's upstream-owned inputs, for tests that
   build with a fixture company/ overlay without touching the real checkout.
   The copy's company/ holds only the upstream README. */
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),zlib=require('node:zlib');
const ROOT=path.join(__dirname,'../..');
// Generated by the build; everything else copied is upstream-owned input.
const GENERATED=new Set(['template/flowview.html','workbench/flowspec.html','workbench/diagrams.json','tools/canon/generated-runtime.cjs']);
const SKIP=new Set(['node_modules','__pycache__','.git']);

function copyTree(from,to){
  for(const entry of fs.readdirSync(from,{withFileTypes:true})){
    if(SKIP.has(entry.name))continue;
    const source=path.join(from,entry.name),target=path.join(to,entry.name);
    if(entry.isDirectory()){fs.mkdirSync(target,{recursive:true});copyTree(source,target);}
    else if(entry.isFile()&&!GENERATED.has(path.relative(ROOT,source).split(path.sep).join('/'))){
      fs.mkdirSync(path.dirname(target),{recursive:true});fs.copyFileSync(source,target);
    }
  }
}
function copyCheckout(checkout){
  copyTree(ROOT,checkout);
  fs.rmSync(path.join(checkout,'company'),{recursive:true,force:true});
  fs.mkdirSync(path.join(checkout,'company'));
  fs.copyFileSync(path.join(ROOT,'company/README.md'),path.join(checkout,'company/README.md'));
  fs.rmSync(path.join(checkout,'workbench/site.json'),{force:true});
}
function inventory(root,relative='',out={}){
  for(const entry of fs.readdirSync(path.join(root,relative),{withFileTypes:true})){
    const name=path.posix.join(relative,entry.name);
    if(SKIP.has(entry.name))continue;
    if(entry.isDirectory())inventory(root,name,out);
    else out[name]=crypto.createHash('sha256').update(fs.readFileSync(path.join(root,name))).digest('hex');
  }
  return out;
}
function kitFiles(html){
  const envelope=JSON.parse(html.match(/<script[^>]+id="flowview-folder-kit"[^>]*>(.*?)<\/script>/s)[1]);
  return JSON.parse(zlib.gunzipSync(Buffer.from(envelope.gzip,'base64'))).files;
}
module.exports={GENERATED,copyCheckout,inventory,kitFiles};
